import{_ as n,l,o as s,c as r,v as t,p as i,x as e,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Gustafson 定律","description":"","frontmatter":{"title":"Gustafson 定律","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gustafson-law.md","filePath":"cs/gustafson-law.md","lastUpdated":1789023840000}'),u={name:"cs/gustafson-law.md"};function c(f,a,A,m,_,E){const o=l("Mermaid");return s(),r("div",null,[a[1]||(a[1]=t('<h1 id="gustafson-定律" tabindex="-1">Gustafson 定律 <a class="header-anchor" href="#gustafson-定律" aria-label="Permalink to &quot;Gustafson 定律&quot;">​</a></h1><div class="epigraph"><p>Amdahl 钉死的是固定工作量下的加速比；Gustafson 说机器变大时工作量也变大，串行段占比可以下降，扩展才有意义。</p><footer>—— 据 Gustafson, Reevaluating Amdahl&#39;s Law, CACM 1988 整理</footer></div><p><a href="/cs/multi-socket-interconnect">上一课</a> 让并行机可以加 socket。<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a> 已经给出固定问题规模的上限。本课不重讲 NUMA 链路。缺口是 <strong>Gustafson：规模可变时的加速比定义</strong>，避免「永远 5% 串行所以 20 核封顶」被误用到弱扩展场景。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Amdahl：工作量 \\(W\\) 固定，\\(s\\) 为串行比例，加速比 \\(\\le 1/(s+(1-s)/n)\\)。科学计算常在核数增加时把网格加密：并行段涨，串行初始化几乎不变。缺口不是新的 NoC，而是<strong>换分子：把 \\(n\\) 核上跑得动的更大问题当作「同等时间」，定义加速比。</strong></p><p><span class="marginnote">Gustafson 的缩放加速比：\\(s+n(1-s)\\) 形式（记号随文本而异）：串行时间固定、并行工作随 \\(n\\) 线性涨时，效率可以保持。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定时间：允许 \\(W_p(n)\\) 增长。报告时必须声明：问题规模、以及串行段是否真的不随 \\(n\\) 涨（I/O、规约树、一致性热点会涨）。与 <a href="/cs/false-sharing">伪共享</a>、跨 socket 延迟：这些会让「并行段」里长出新的串行/争用，Gustafson 不会自动成立。</p><p>另一种误读：把「更多核跑更大网格」的墙钟几乎不变当成强扩展成功。那是弱扩展。用户若要同一网格更快，必须看 Amdahl 曲线。</p>',9)),(s(),i(p,null,{default:e(()=>[h(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20AMD%5B%22Amdahl%EF%BC%9AW%20%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20CAP%5B%22%E6%A0%B8%E6%95%B0%E5%BE%88%E5%BF%AB%E5%B0%81%E9%A1%B6%22%5D%0A%20%20GUS%5B%22Gustafson%EF%BC%9AW%20%E9%9A%8F%20n%20%E6%B6%A8%22%5D%20--%3E%20KEEP%5B%22%E5%9B%BA%E5%AE%9A%E6%97%B6%E9%97%B4%E5%86%85%E5%81%9A%E6%9B%B4%E5%A4%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课强/弱扩展把这两种实验设计说成实验室标准：强扩展 ≈ Amdahl 实验；弱扩展 ≈ Gustafson 精神。SPEC 再下一课会警告：基准往往固定输入，更像 Amdahl。</p><p>本栏不把集群作业调度写成定律证明。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不修改 Amdahl 的数学，只加规模假设。串行段随日志因子涨（规约）时两条定律都要修正。强/弱扩展术语下一课钉死。</p><p>后课默认：谈加速比先报问题规模是否随机器变。实验怎么画曲线，用强/弱扩展这对词。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Amdahl 固定工作量；Gustafson 允许工作量随核数增长。</li><li>争用与 I/O 会破坏「串行段不变」的假设。</li><li>强扩展与弱扩展是下一课的实验语言。</li><li>出处：Gustafson, <em>CACM</em>, 1988；Amdahl。</li></ul>',8))])}const C=n(u,[["render",c]]);export{g as __pageData,C as default};
